// Example of undefined behavior due to uninitialized pointer
int *ptr; // uninitialized pointer
*ptr = 42; // UB: dereferencing uninitialized pointer

// Example of implementation-defined behavior with signed overflow
int a = INT_MAX;
a = a + 1; // Signed overflow, behavior is implementation-defined

// Example of violating strict aliasing rules
float f = 3.14f;
int *ip = (int*)&f; // violating strict aliasing
*ip = 42; // Undefined behavior
